N = 300
rows = []
for cat, s_ in ITEMS.items():
    items = list(dict.fromkeys(s_.split("|") + EXTRA[cat].split("|") + EXTRA2[cat].split("|")))
    chosen = {(random.choice(TEMPLATES).format(i), i) for i in items}   # every item appears at least once
    pool = [(t.format(i), i) for i in items for t in TEMPLATES]
    random.shuffle(pool)
    for p in pool:
        if len(chosen) >= N: break
        chosen.add(p)
    for desc, grp in chosen:
        rows.append((desc, cat, grp))
df = pd.DataFrame(rows, columns=["description", "category", "group"]).drop_duplicates("description")
